            "`$thumb`.`alt` as `$thumb.alt`",
            "`$thumb`.`add` as `$thumb.add`",
        ));

        if (!empty($includeOriginal)) {
            ${$join}[] = array(
                \'class\' => \'msResourceFile\',
                \'alias\' => $thumb . \'o\',
                \'on\' => "`{$thumb}o`.`id` = `$thumb`.`parent`",
